/** A rollback-only migration planner must not lend its dictionary writer to unrelated creating callers. */
@Timeout(45)
class LmdbLegacyAliasPlanningAdmissionRegressionTest {
	@ParameterizedTest
	@EnumSource(Creation.class)
	void creationWaitsForAnEmptyMigrationPlanAndRemainsCommitted(Creation creation,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		verifyPlanningAdmission(creation, directory, false);
	}

	@ParameterizedTest
	@EnumSource(Creation.class)
	void creationWaitsForDirectPlannerAndRemainsCommitted(Creation creation,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		verifyPlanningAdmission(creation, directory, true);
	}

	private void verifyPlanningAdmission(Creation creation, Path directory, boolean directPlanner) throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", directory);
		CountDownLatch rollbackEntered = new CountDownLatch(1);
		CountDownLatch releaseRollback = new CountDownLatch(1);
		CapturedStore store = new CapturedStore(directory, rollbackEntered, releaseRollback);
		ExecutorService planner = Executors.newSingleThreadExecutor();
		ExecutorService creator = Executors.newSingleThreadExecutor();
		CountDownLatch scanEntered = new CountDownLatch(1);
		CountDownLatch releaseScan = new CountDownLatch(1);
		CountDownLatch creationEntered = new CountDownLatch(1);
		AtomicBoolean intercepted = new AtomicBoolean();
		AtomicReference<Thread> creatorThread = new AtomicReference<>();
		try {
			store.init();
			LmdbSailStore backing = store.getBackingStore();
			ValueStore values = (ValueStore) backing.getValueFactory();
			IRI value = SimpleValueFactory.getInstance().createIRI("urn:planning-admission:" + creation + ":owner");
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(value), "the created owner must not already exist");
			store.pausePlannerRollback.set(true);
			Future<LmdbLanguageTagVariantMerge.Outcome> migration = planner.submit(() -> {
				try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
					if (invocation.getMethod().getName().equals("mdb_cursor_get")
							&& hasFrame("planLanguageLiteralGroups") && intercepted.compareAndSet(false, true)) {
						scanEntered.countDown();
						if (!releaseScan.await(20, TimeUnit.SECONDS)) {
							throw new IOException("planning scan was not released");
						}
					}
					return CALLS_REAL_METHODS.answer(invocation);
				})) {
					if (directPlanner) {
						LanguageTagVariantMergePlan plan = values.planLanguageTagVariantMerge();
						return new LmdbLanguageTagVariantMerge.Outcome(plan.variantGroups(), plan.loserCount(), 0L);
					}
					return LmdbLanguageTagVariantMerge.mergeIfRequired(values, backing.getTripleStore(), directory);
				}
			});
			assertTrue(scanEntered.await(10, TimeUnit.SECONDS), "the native dictionary planning scan must be held");
			IOException explicitWriter = assertThrows(IOException.class, () -> values.startTransaction(false));
			assertTrue(explicitWriter.getMessage().contains("already has an active write transaction"),
					"a competing explicit writer must be rejected while the planner owns the dictionary");
			Future<Long> created = creator.submit(() -> {
				creatorThread.set(Thread.currentThread());
				creationEntered.countDown();
				if (creation == Creation.SINGLE) {
					return values.getId(value, true);
				}
				long[] ids = new long[1];
				values.storeValues(new Value[] { value }, ids, 1);
				return ids[0];
			});
			assertTrue(creationEntered.await(10, TimeUnit.SECONDS), "the creating caller must enter during planning");
			boolean waitedDuringScan = reachedWriterAdmissionOrCompleted(created, creatorThread, true);
			releaseScan.countDown();
			assertTrue(rollbackEntered.await(10, TimeUnit.SECONDS),
					"the planner must reach its real rollback boundary after releasing the scan");
			boolean waited = reachedWriterAdmissionOrCompleted(created, creatorThread, false);
			boolean completedDuringPlanning = created.isDone();
			releaseRollback.countDown();
			LmdbLanguageTagVariantMerge.Outcome outcome = migration.get(10, TimeUnit.SECONDS);
			long id = created.get(10, TimeUnit.SECONDS);
			long resolved = values.getId(value);
			byte[] owner = values.getData(id);
			assertAll(
					() -> assertTrue(intercepted.get(), "the test must overlap the real native planner"),
					() -> assertTrue(waitedDuringScan, "the creating caller must reach a real wait during the scan"),
					() -> assertEquals(0, outcome.mergedValueIds(), "the test must use a rollback-only empty plan"),
					() -> assertFalse(completedDuringPlanning,
							"creation must not complete inside the planner's writer"),
					() -> assertTrue(waited, "creation must wait for exclusive migration authority"),
					() -> assertTrue(id > 0L, "creation must succeed after migration"),
					() -> assertEquals(id, resolved, "the reported owner must remain discoverable after planning"),
					() -> assertNotNull(owner, "the reported owner must remain committed after planning"));
		} finally {
			releaseScan.countDown();
			releaseRollback.countDown();
			planner.shutdownNow();
			creator.shutdownNow();
			assertTrue(planner.awaitTermination(10, TimeUnit.SECONDS));
			assertTrue(creator.awaitTermination(10, TimeUnit.SECONDS));
			store.shutDown();
		}
	}

	@Test
	@Timeout(10)
	void activeSameThreadWriterIsRejectedWithoutBeingConsumed(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", directory);
		CapturedStore store = new CapturedStore(directory, new CountDownLatch(1), new CountDownLatch(1));
		try {
			store.init();
			ValueStore values = (ValueStore) store.getBackingStore().getValueFactory();
			IRI value = SimpleValueFactory.getInstance().createIRI("urn:planning-reentrant:owner");
			values.startTransaction(false);
			boolean committed = false;
			try {
				IOException failure = assertThrows(IOException.class, values::planLanguageTagVariantMerge);
				assertTrue(failure.getMessage().contains("already has an active write transaction"));
				long id = values.getId(value, true);
				values.commit();
				committed = true;
				assertEquals(id, values.getId(value), "the original writer must remain usable and committed");
			} finally {
				if (!committed) {
					values.rollback();
				}
			}
		} finally {
			store.shutDown();
		}
	}

	private static boolean reachedWriterAdmissionOrCompleted(Future<?> created, AtomicReference<Thread> caller,
			boolean scanning) throws IOException {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (!created.isDone()) {
			Thread thread = caller.get();
			if (thread != null && thread.getState() == Thread.State.WAITING) {
				for (StackTraceElement frame : thread.getStackTrace()) {
					if (frame.getClassName().equals(ValueStore.class.getName())
							&& (frame.getMethodName().equals("enterStandaloneValueWriter")
									|| frame.getMethodName().equals("awaitJoinableWriter")
									|| scanning && frame.getMethodName().equals("acquireAssociationGate"))) {
						return true;
					}
				}
			}
			if (System.nanoTime() >= deadline) {
				throw new IOException("creating caller reached neither completion nor writer admission");
			}
			Thread.onSpinWait();
		}
		return false;
	}

	private static boolean hasFrame(String method) {
		for (StackTraceElement frame : Thread.currentThread().getStackTrace()) {
			if (frame.getClassName().equals(ValueStore.class.getName()) && frame.getMethodName().equals(method)) {
				return true;
			}
		}
		return false;
	}

	private enum Creation {
		SINGLE,
		BATCH
	}

	private static final class CapturedStore extends LmdbStore {
		private final CountDownLatch rollbackEntered;
		private final CountDownLatch releaseRollback;
		private final AtomicBoolean pausePlannerRollback = new AtomicBoolean();
		private final AtomicBoolean paused = new AtomicBoolean();

		private CapturedStore(Path directory, CountDownLatch rollbackEntered, CountDownLatch releaseRollback) {
			super(directory.toFile(), new LmdbStoreConfig().setSketchEstimatorEnabled(false)
					.setPredicateGuaranteeIndexEnabled(false));
			this.rollbackEntered = rollbackEntered;
			this.releaseRollback = releaseRollback;
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			LmdbSailStore.ValueStoreFactory values = (path, stored, selected) -> new ValueStore(path, stored, selected,
					false, null, LmdbStoreFormat.fromProperties(stored, selected), true) {
				@Override
				public void rollback() throws IOException {
					if (pausePlannerRollback.get() && hasFrame("planLanguageTagVariantMerge")
							&& paused.compareAndSet(false, true)) {
						rollbackEntered.countDown();
						try {
							if (!releaseRollback.await(20, TimeUnit.SECONDS)) {
								throw new IOException("planner rollback was not released");
							}
						} catch (InterruptedException interrupted) {
							Thread.currentThread().interrupt();
							throw new IOException("interrupted while holding planner rollback", interrupted);
						}
					}
					super.rollback();
				}
			};
			return new LmdbSailStore(directory, properties, config, sketches, values, TripleStore::new) {
				@Override
				void startBackgroundMaintenanceAfterInitialization() {
					// Keep unrelated maintenance out of the held native planning transaction.
				}
			};
		}
	}
}
